pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 fundAmount, uint256 withdrawAmount) public {
        fundAmount = bound(fundAmount, 1, 1 ether);
        withdrawAmount = bound(withdrawAmount, 0, 2 ether);

        Reverter bad = new Reverter();

        vm.deal(address(this), fundAmount);
        (bool s, ) = address(c).call{value: fundAmount}("");
        require(s);

        uint256 before = address(c).balance;

        OwnerCaller caller = new OwnerCaller(c);

        acceptPayments = (withdrawAmount % 2 == 0);

        uint256 beforeBalance = address(c).balance;

        bool ok;
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.assume(withdrawAmount <= beforeBalance);

        if (ok) {
            assertTrue(address(c).balance == beforeBalance - withdrawAmount);
        } else {
            assertTrue(true);
        }
    }

    bool acceptPayments;
    receive() external payable {
        if (!acceptPayments) revert("no accept");
    }
}

contract Reverter { fallback() external payable { revert(); } }

contract OwnerCaller {
    SimpleWallet c;
    constructor(SimpleWallet _c) { c = _c; }
    function callWithdraw(uint256 amount) external {
        c.withdraw(amount);
    }
}
